const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function renderPackages(filter='all'){$('#package-grid').innerHTML=packages.filter(p=>filter==='all'||(filter==='gorilla'?['bunyonyi','luxury','private'].includes(p.id):['murchison','semliki'].includes(p.id))).map(p=>`<article class="package-card"><div class="package-photo"><img src="assets/${p.image}" alt="${p.name}" loading="lazy"><span>${p.duration}</span></div><small>${p.tag}</small><h3>${p.name}</h3><p>${p.desc}</p><div class="package-price"><div><small>${p.high===p.low?'':'From '}</small><strong>${money(p.low)}</strong> <small>/ person</small></div><button class="arrow" data-detail="${p.id}" aria-label="View ${p.name}">↗</button></div></article>`).join('');}renderPackages();
$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderPackages(b.dataset.filter)});
$('#destination-grid').innerHTML=destinations.map(d=>`<button class="destination" data-destination="${d[0]}"><img src="assets/${d[1]}" alt="${d[0]} landscape and wildlife" loading="lazy"><div><h3>${d[0]} ↗</h3><p>${d[2]}</p></div></button>`).join('');
const serviceNames=['Uganda Safaris','Gorilla & Chimp Trekking','Flight Booking','Hotel Reservations','Passport & Visa Assistance','Car Hire & Transport','Group & Family Travel','International Travel'];const serviceDescriptions=['Wildlife, national parks and unforgettable safari experiences.','Professional arrangements for gorilla and chimpanzee trekking.','Flight reservations and ticketing for local and international journeys.','Accommodation bookings in Uganda and around the world.','Guidance and assistance with passport and visa processes.','Convenient transport and car hire for travelers and groups.','Customized family, educational, group and corporate travel.','Holidays, business travel, pilgrimages and honeymoon trips.'];const paths=['M3 20 9 4l4 10 3-6 5 12H3Z','M12 21V10m0 6C2 16 3 6 3 6s9 0 9 10Zm0-5c0-8 9-9 9-9s1 10-9 9Z','m3 11 7 2 2 8 2-1 1-6 5-5c3-3 0-4-2-2l-5 4-7-2Z','M4 21V3h16v18M2 21h20M8 7h2m4 0h2M8 11h2m4 0h2M9 21v-5h6v5','M5 3h14v18H5ZM9 8h6M9 12h6M9 16h3','M3 17V9l3-5h12l3 5v8H3Zm0-7h18M6 17v3m12-3v3M6 13h2m8 0h2','M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-6 10v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a4 4 0 0 1 3 4v2','M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z'];$('#service-grid').innerHTML=serviceNames.map((n,i)=>`<article class="service"><svg viewBox="0 0 24 24" fill="none" stroke-width="1.3" aria-hidden="true"><path d="${paths[i]}"/></svg><h3>${n}</h3><p>${serviceDescriptions[i]}</p><button class="text-link" data-destination="${n}">Let’s arrange it ↗</button></article>`).join('');
const social=[['Instagram','https://www.instagram.com/whmandaabm2026','M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5Zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3Zm5 3a5 5 0 1 1 0 10 5 5 0 0 1 0-10Zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6Zm6-4a1 1 0 1 1 0 2 1 1 0 0 1 0-2Z'],['TikTok','https://www.tiktok.com/@whmandaabm','M14 2h3c.3 3 2 4 5 4v3c-2 0-4-.7-5-1.6V16a6 6 0 1 1-6-6v3a3 3 0 1 0 3 3Z'],['X','https://x.com/whmandaabm2026','M3 3h5l5 7 6-7h2l-7 9 8 9h-5l-6-7-6 7H2l8-9Zm3 2 12 14h1L7 5Z']];$('#socials').innerHTML=social.map(s=>`<a href="${s[1]}" target="_blank" rel="noopener" aria-label="${s[0]}" title="${s[0]}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${s[2]}"/></svg></a>`).join('');
$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$$('nav a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});
const form=$('#booking-form');let step=1;let summary='';$('#trip').innerHTML=packages.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')+'<option value="custom">A custom trip / travel service</option>';
const date=new Date();date.setMinutes(date.getMinutes()-date.getTimezoneOffset());form.elements.date.min=date.toISOString().slice(0,10);
function showStep(n){step=n;$$('.step').forEach(s=>s.hidden=+s.dataset.step!==n);$$('.steps span').forEach((s,i)=>s.classList.toggle('active',i===n-1));$('#booking').scrollTop=0;$('.step:not([hidden]) input, .step:not([hidden]) select, .step:not([hidden]) button')?.focus();}
function openBooking(id='',notes=''){form.reset();$('#trip').value=id||'bunyonyi';form.elements.notes.value=notes;form.elements.terms.checked=false;$('#copy-status').textContent='';showStep(1);sharingVisibility();$('#booking').showModal();}
function sharingVisibility(){$('#sharing-row').hidden=$('#trip').value!=='bunyonyi';}$('#trip').onchange=sharingVisibility;
function validStep(){return [...$('.step:not([hidden])').querySelectorAll('input,select,textarea')].every(el=>el.reportValidity())}
$$('.next').forEach(b=>b.onclick=()=>{if(!validStep())return;if(step===2)buildQuote();showStep(step+1)});$$('.back').forEach(b=>b.onclick=()=>showStep(step-1));
function buildQuote(){const d=Object.fromEntries(new FormData(form));const p=packages.find(p=>p.id===d.trip);const n=+d.travelers;const q=quote(p,n,d.sharing==='on');const name=p?p.name:'Custom trip / travel service';$('#quote').replaceChildren();const box=document.createElement('div');box.className='quote-box';for(const [tag,text] of [['p',name],['strong',q.text],['p',q.detail],['p',`${d.date} · ${n} travelers · ${d.stay}`],['small','Indicative estimate based on published rates, subject to availability and the team’s confirmation. Accommodation changes, dates, permits and additional activities may affect the final quote.']]){const el=document.createElement(tag);el.textContent=text;box.append(el)}$('#quote').append(box);summary=`Hello WHM & AABM!\n\n*TRIP ENQUIRY*\nJourney: ${name}\nDeparture: ${d.date}\nTravelers: ${n}\nAccommodation: ${d.stay}\nGroup sharing: ${p?.id==='bunyonyi'&&d.sharing==='on'?'Yes':'No / not applicable'}\n\n*INDICATIVE ESTIMATE (USD)*\n${q.text}\n${q.detail}\nSubject to availability and final confirmation.\n\n*CONTACT DETAILS*\nName: ${d.name}\nWhatsApp: ${d.phone}\nEmail: ${d.email}\n\n*REQUESTS*\n${d.notes||'No additional requests.'}\n\nPlease confirm availability, the itinerary and the final quotation. I have reviewed your booking and cancellation policies.`;}
form.onsubmit=e=>{e.preventDefault();if(step!==3||!validStep())return;buildQuote();window.open('https://wa.me/256703023337?text='+encodeURIComponent(summary),'_blank','noopener,noreferrer')};$('#copy-summary').onclick=async()=>{if(!validStep())return;buildQuote();try{await navigator.clipboard.writeText(summary);$('#copy-status').textContent=' Enquiry copied.'}catch{$('#copy-status').textContent=' Copy unavailable in this browser. Please continue on WhatsApp.'}};
$('#read-policies').onclick=()=>$('#booking').close();$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('click',e=>{const book=e.target.closest('[data-book]');const dest=e.target.closest('[data-destination]');const detail=e.target.closest('[data-detail]');if(book){$('#tour-detail').close();openBooking(book.dataset.book)}if(dest)openBooking('custom',`I’m interested in ${dest.dataset.destination}.`);if(detail){const p=packages.find(p=>p.id===detail.dataset.detail);$('#tour-content').innerHTML=`<img src="assets/${p.image}" alt="${p.name}"><div class="eyebrow">${p.duration}</div><h2>${p.name}</h2><p>${p.desc}</p><p><strong>${p.high&&p.high!==p.low?`${money(p.low)}–${money(p.high)}`:(p.high?'':'From ')+money(p.low)} USD per person</strong>${p.group?`<br>${money(p.group)} per person for groups of 3 or more sharing.`:''}</p>${p.id==='murchison'?'<p>Price depends on group size.</p>':''}${p.includes.length?'<h3>Included in your journey</h3><ul>'+p.includes.map(i=>`<li>${i}</li>`).join('')+'</ul>':'<p>Your itinerary, inclusions and accommodation will be confirmed with the team.</p>'}<p><strong>Ideal for:</strong> ${p.ideal}</p><button class="button" data-book="${p.id}">Plan this journey ↗</button>`;$('#tour-detail').showModal()}});
